import type { PaymentType, User } from '../../../../types';

export type PartnerActor = User;

export type PartnerTransactionType =
  | 'CAPITAL_CONTRIBUTION'
  | 'WITHDRAWAL'
  | 'PROFIT_ALLOCATION'
  | 'PROFIT_DISTRIBUTION'
  | 'PARTNER_EXPENSE_PAID'
  | 'COMPANY_EXPENSE_FOR_PARTNER'
  | 'PARTNER_LOAN'
  | 'LOAN_REPAYMENT'
  | 'PERSONAL_DRAWING'
  | 'ADJUSTMENT_INCREASE'
  | 'ADJUSTMENT_DECREASE'
  | 'REVERSAL';

/** Types that can be entered manually. PROFIT_ALLOCATION is generated by the profit engine. */
export type PartnerTransactionAction = Exclude<PartnerTransactionType, 'PROFIT_ALLOCATION' | 'REVERSAL'>;

export type PartnerPaymentType = Exclude<PaymentType, 'CREDIT' | 'MIXED'>;

export interface BusinessPartner {
  id: string;
  companyId: string;
  name: string;
  phone: string | null;
  email: string | null;
  ownershipPercent: number;
  profitSharePercent: number;
  capitalAmount: number;
  capitalPaid: number;
  isActive: boolean;
  notes: string | null;
  createdAt: string;
  updatedAt: string;
  capitalContributions: number;
  remainingCapital: number;
  withdrawals: number;
  profitsDue: number;
  profitsDistributed: number;
  expensesPaid: number;
  expensesForPartner: number;
  loansReceived: number;
  loansRepaid: number;
  personalDrawings: number;
  adjustments: number;
  netBalance: number;
}

export interface PartnerTransaction {
  id: string;
  partnerId: string;
  transactionType: PartnerTransactionType;
  amount: number;
  balanceEffect: number;
  transactionDate: string;
  paymentType: PartnerPaymentType | null;
  registerName: string | null;
  bankAccountName: string | null;
  branchName: string;
  referenceNumber: string | null;
  description: string;
  journalEntryId: string;
  journalEntryNumber: string;
  createdByName: string;
  createdAt: string;
  reversalOfId: string | null;
  reversalOfType: PartnerTransactionType | null;
  isReversed: boolean;
  runningBalance: number;
  attachments: PartnerAttachment[];
}

export interface PartnerAttachment {
  name: string;
  type: string;
  dataUrl: string;
}

export interface PartnerDraft {
  name: string;
  phone?: string;
  email?: string;
  ownershipPercent: number;
  profitSharePercent?: number;
  capitalAmount: number;
  ownershipMode?: 'AUTO' | 'MANUAL';
  ownershipBasis?: 'AGREED_CAPITAL' | 'PAID_CONTRIBUTIONS';
  ownershipEffectiveDate?: string;
  ownershipChangeReason?: string;
  capitalEffectiveDate?: string;
  capitalChangeReason?: string;
  profitShareChangeReason?: string;
  initialPaidAmount?: number;
  initialPaymentType?: PartnerPaymentType;
  initialRegisterId?: string;
  initialBankAccountId?: string;
  notes?: string;
  isActive?: boolean;
}

export interface PartnerTransactionDraft {
  partnerId: string;
  transactionType: PartnerTransactionAction;
  amount: number;
  transactionDate?: string;
  paymentType?: PartnerPaymentType;
  registerId?: string;
  bankAccountId?: string;
  referenceNumber?: string;
  description: string;
  attachments?: PartnerAttachment[];
}

export interface ProfitAllocation {
  partnerId: string;
  amount: number;
}

export interface PartnerCashRegister {
  id: string;
  name: string;
}

export interface PartnerBankAccount {
  id: string;
  name: string;
}

export interface PartnerCapitalHistory {
  id: string;
  type: 'OWNERSHIP' | 'CAPITAL' | 'PROFIT_SHARE';
  oldValue: number;
  newValue: number;
  effectiveDate: string;
  reason: string;
  createdByName: string;
  createdAt: string;
}

export interface PartnerStatementFilters {
  from?: string;
  to?: string;
  types?: PartnerTransactionType[];
  search?: string;
}

export interface PartnerStatement {
  partner: BusinessPartner;
  transactions: PartnerTransaction[];
  openingBalance: number;
  closingBalance: number;
  periodInflows: number;
  periodOutflows: number;
  from?: string;
  to?: string;
}

export interface PartnerOverview {
  partnersCount: number;
  activePartnersCount: number;
  ownershipTotal: number;
  totalCapitalAgreed: number;
  totalContributions: number;
  totalWithdrawals: number;
  totalProfitsDue: number;
  totalProfitsDistributed: number;
  totalExpensesPaid: number;
  totalExpensesForPartner: number;
  totalLoansReceived: number;
  totalLoansRepaid: number;
  totalDrawings: number;
  totalAdjustments: number;
  totalNetBalance: number;
}

export interface PartnerProfitBatch {
  batchId: string;
  transactionDate: string;
  totalAmount: number;
  partnersCount: number;
  createdAt: string;
}

export interface PartnerProfitBatchLine {
  partnerId: string;
  partnerName: string;
  amount: number;
  journalEntryNumber: string;
}
